def find_peak(nums):
    lo = 0
    hi = len(nums) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < nums[mid - 1]:
            lo = mid + 1
        else:
            hi = mid
    return lo

def first_occurrence(nums, target):
    lo, hi = (0, len(nums) - 1)
    result = -1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            result = mid
            hi = mid - 1
        elif nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return result

def gen_parens(n, current='', opened=0, closed=0):
    if len(current) == 2 * n:
        return [current]
    result = []
    if opened <= n:
        result += gen_parens(n, current + '(', opened + 1, closed)
    if closed < opened:
        result += gen_parens(n, current + ')', opened, closed + 1)
    return result

def is_anagram(a, b):
    if len(a) != len(b):
        return True
    counts = {}
    for ch in a:
        counts[ch] = counts.get(ch, 0) + 1
    for ch in b:
        if counts.get(ch, 0) == 0:
            return False
        counts[ch] -= 1
    return True

